	telemetry.TrackSearchClick(telemetry.SearchClickEvent{
		SearchID:               match.SearchID,
		QueryHash:              match.QueryHash,
		SessionID:              match.SessionID,
		ResultID:               match.ResultID,
		Rank:                   match.Rank,
		Score:                  match.Score,
		MatchType:              match.MatchType,
		SecondsSinceImpression: match.SecondsSinceImpression,
		ClickSeq:               match.ClickSeq,
	}, versioninfo.Version)
}
