// trackSearchImpressions persists the served impression set and emits a
// cli_search_performed event when telemetry is opted in
// (settings.Telemetry == true). Best-effort and silent on failure: search
// output has already been written, tracking must never break it. The session
// id is the most-recent-session heuristic — best-effort metadata, not the
// correlation key (that's search_id + result_id).
func trackSearchImpressions(ctx context.Context, searchID, query, mode string, total, page, limit int, impressions []telemetry.SearchImpression) {
	if searchID == "" || len(impressions) == 0 {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil || s.Telemetry == nil || !*s.Telemetry {
		return
	}
	path, err := searchImpressionsPath(ctx)
	if err != nil {
		return
	}
	now := time.Now()
	rec := impressionRecord{
		SearchID:  searchID,
		QueryHash: hashSearchQuery(query),
		SessionID: strategy.FindMostRecentSessionInCurrentWorktree(ctx),
		Timestamp: now,
	}
	rec.Results = make([]storedImpression, 0, len(impressions))
	for _, imp := range impressions {
		rec.Results = append(rec.Results, storedImpression{SearchImpression: imp})
	}
	prevSearchID, prevClicked, err := recordImpressions(path, rec, now)
	if err != nil {
		return
	}
	telemetry.TrackSearchPerformed(telemetry.SearchPerformedEvent{
		SearchID:          searchID,
		QueryHash:         rec.QueryHash,
		SessionID:         rec.SessionID,
		Mode:              mode,
		Total:             total,
		Page:              page,
		Limit:             limit,
		Impressions:       impressions,
		PrevSearchID:      prevSearchID,
		PrevSearchClicked: prevClicked,
	}, versioninfo.Version)
}
