func TestHashSearchQuery_NormalizesAndTruncates(t *testing.T) {
	t.Parallel()
	a := hashSearchQuery("  Foo   BAR ")
	b := hashSearchQuery("foo bar")
	if a != b {
		t.Errorf("normalized hashes differ: %q vs %q", a, b)
	}
	if len(a) != 16 {
		t.Errorf("hash length = %d, want 16", len(a))
